INSERT INTO `pages` (`id`, `name`, `content`, `user_id`, `image`, `template`, `description`, `status`, `created_at`, `updated_at`) VALUES
(1, 'Consulting in Bangladesh', '<shortcode>[hero-banner style=\"style-1\" title=\"বিজনেস &nbsp;ও প্রযুক্তি পরামর্শদাতা\" subtitle=\"আমরা এই ক্ষেত্রে বিশেষজ্ঞ\" description=\"আপনার ব্যবসাকে ন্যায়সঙ্গত, টেকসই এবং আধুনিক করতে চাইলে আপনি সঠিক জায়গায় এসেছেন। আমরা ইসলামের নৈতিক নীতিমালা এবং আধুনিক প্রযুক্তির সমন্বয়ে এমন ব্যবসায়িক পরামর্শ ও প্রযুক্তিগত সমাধান প্রদান করি, যা আপনার ব্যবসাকে শুধু লাভজনক নয়, বরং সমাজের জন্য কল্যাণকর করে তুলবে। আমাদের লক্ষ্য হলো ব্যবসার মাধ্যমে আপনার জন্য অর্থনৈতিক সমৃদ্ধি আনা এবং ইসলামের আদর্শ মেনে একটি ন্যায়সঙ্গত এবং সাফল্যময় ব্যবসার পরিবেশ তৈরি করা। যোগাযোগ করুন এবং আপনার ব্যবসার জন্য উপযুক্ত সমাধান খুঁজে নিন!\" button_label=\"আমাদের সেবাসমূহ\" button_url=\"/services\" button_play_video_label=\"ভিডিওটি দেখুন\" youtube_url=\"https://www.youtube.com/watch?v=dxOGJUc2wtQ\" image=\"delowar.png\" background_image=\"backgrounds/finance-banner-bg.png\" background_image_1=\"backgrounds/banner-shape01.png\" background_image_2=\"backgrounds/banner-shape02.png\" background_image_3=\"backgrounds/banner-shape03.png\"][/hero-banner]</shortcode><shortcode>[featured-service-categories style=\"style-1\" category_ids=\"4,5,7\" enable_lazy_loading=\"yes\"][/featured-service-categories]</shortcode><shortcode>[about-us-information style=\"style-1\" title=\"Business Courses, Technology Consultations &amp; Resource\" subtitle=\"আমাদের সম্পর্কে জানুন\" description=\"আমি দিলোয়ার হোসেন , ইসলামী নীতিমালা এবং আধুনিক প্রযুক্তির সমন্বয়ে সুষ্ঠু ও ন্যায়সঙ্গত ব্যবসা পরিচালনার জন্য পরামর্শ ও দিকনির্দেশনা প্রদান করি। আমার লক্ষ্য হলো ব্যবসায়িক সাফল্য ও সমাজের কল্যাণকে একত্রে নিশ্চিত করা, যেখানে হালাল ব্যবসার নীতিমালা এবং প্রযুক্তিগত উদ্ভাবন আপনাকে এগিয়ে নিয়ে যাবে।\" founded_year=\"2018\" company_description=\"আমাদের সাথে যোগাযোগ করুন এবং আপনার ব্যবসার জন্য সর্বোচ্চ প্রযুক্তিগত সহায়তা পান।\" quantity=\"8\" title_1=\"ওয়েবসাইট ডেভেলপমেন্ট ও ডিজাইন\" icon_1=\"0\" title_2=\"ডিজিটাল মার্কেটিং ও ব্র্যান্ডিং স্ট্র্যাটেজি\" icon_2=\"0\" title_3=\"সাইবার নিরাপত্তা ও ঝুঁকি ব্যবস্থাপনা\" icon_3=\"0\" title_4=\"কনটেন্ট ক্রিয়েশন ও ই-কমার্স সলিউশন\" icon_4=\"0\" title_5=\"সফটওয়্যার ডেভেলপমেন্ট ও অটোমেশন\" icon_5=\"0\" title_6=\"টেকনিকেল আইটি সাপোর্ট &nbsp;ও ডেটা ম্যানেজমেন্ট\" icon_6=\"0\" title_7=\"ইসলামিক বিজনেস মডেল তৈরি\" icon_7=\"0\" title_8=\"প্রশিক্ষণ ও দক্ষতা উন্নয়ন\" icon_8=\"0\" sub_description=\"আমাদের দক্ষ দল আপনার ব্যবসার প্রযুক্তিগত প্রয়োজন অনুযায়ী কাস্টমাইজড সমাধান প্রদান করে। প্রযুক্তির সঠিক ব্যবহার নিশ্চিত করে আপনার ব্যবসার উন্নয়ন ও প্রতিযোগিতামূলক বাজারে এগিয়ে থাকার সুযোগ করে দেবে। আমাদের সাথে যোগাযোগ করুন এবং আপনার ইসলামিক বিজনেস মডেল ও &nbsp;প্রযুক্তিগত সহায়তা পান।\" author_name=\"Delowar Hossen , ইসলামিক বিজনেস ও প্রযুক্তি পরামর্শদাতা।\" author_bio=\"CEO, Founder at Workshop IT\" author_avatar=\"delowarbro.png\" author_signature=\"general/signature.png\" image=\"delowar-hossen-1.png\" button_play_video_icon=\"0\" image_1=\"33.PNG\" background_image_1=\"backgrounds/about-shape01.png\" background_image_2=\"backgrounds/about-shape02.png\" background_image_3=\"backgrounds/about-shape03.png\" enable_lazy_loading=\"no\"][/about-us-information]</shortcode><shortcode>[company-overview style=\"style-1\" title=\"ইসলামিক বিজনেস মডেল তৈরি\" subtitle=\" আমাদের ১০ বছরের অভিজ্ঞতা \" description=\"আমাদের ১০ বছরের অভিজ্ঞতায়, আমরা একটি ন্যায়নিষ্ঠ ও নৈতিকভাবে সঠিক ইসলামিক বিজনেস মডেল গড়ে তোলার পথে কাজ করে যাচ্ছি। এই মডেলের মূল ভিত্তি হলো ইসলামের অর্থনৈতিক নীতিমালা, যা সুদমুক্ত ব্যবসা, ন্যায্য বণ্টন, এবং সমাজকল্যাণে মনোনিবেশ করে। আমাদের অভিজ্ঞতা জুড়ে রয়েছে: ইসলামিক অর্থনীতির গভীর বিশ্লেষণ: ব্যবসা পরিচালনায় ইসলামের মূলনীতিগুলোর যথাযথ প্রয়োগ। ন্যায়নিষ্ঠতা ও ট্রাস্ট-বিল্ডিং: ব্যবসায় পারস্পরিক বিশ্বাস এবং স্বচ্ছতা বজায় রাখা। সম্পদ বণ্টনের ন্যায্যতা: লাভ ও ক্ষতির সুষম বণ্টন নিশ্চিত করা। টেকসই উন্নয়ন: ব্যবসার মাধ্যমে সমাজের সামগ্রিক উন্নয়ন নিশ্চিত করা। আমাদের মডেল শুধুমাত্র একটি ব্যবসায়িক কাঠামো নয়, বরং এটি একটি জীবনের দৃষ্টিভঙ্গি, যা আর্থিক লাভের পাশাপাশি আখিরাতের সফলতাকেও নিশ্চিত করে। ইসলামিক আদর্শের আলোকে আপনার ব্যবসাকে নতুন উচ্চতায় নিয়ে যেতে আমাদের অভিজ্ঞতা কাজে লাগান।\" image=\"capture.PNG\" image_1=\"backgrounds/overview-img02.png\" background_image=\"backgrounds/overview-shape.png\" background_image_1=\"backgrounds/overview-img-shape.png\" quantity=\"2\" title_1=\"Best Award\" logo_1=\"flaticon-trophy\" data_1=\"235\" unit_1=\"+\" title_2=\"Happy Clients\" logo_2=\"flaticon-rating\" data_2=\"98\" unit_2=\"K\" enable_lazy_loading=\"yes\"][/company-overview]</shortcode><shortcode>[intro-video title=\" পরামর্শদাতা হিসাবে আমাদের পদক্ষেপ\" description=\"আমরা একটি দায়িত্বশীল ইসলামিক বিজনেস ও প্রযুক্তি পরামর্শদাতা প্রতিষ্ঠান হিসেবে কাজ করছি, যেখানে আধুনিক প্রযুক্তির সঙ্গে ইসলামিক নীতিমালার সমন্বয়ে ব্যবসায়িক উন্নয়নকে এগিয়ে নেওয়া হয়। আমাদের লক্ষ্য হচ্ছে, একটি নৈতিক, ন্যায্য এবং কার্যকর ব্যবসায়িক পরিবেশ গড়ে তোলা যা আখিরাতের সফলতার দিকেও দৃষ্টি নিবদ্ধ করে।\" button_label=\" ভিডিওটি দেখুন\" youtube_video_url=\"https://www.youtube.com/watch?v=dxOGJUc2wtQ\" background_image=\"3.PNG\" background_image_1=\"backgrounds/choose-shape.png\" box_title=\"আমাদের পদক্ষেপ\" box_subtitle=\"১০০% ইসলামিক বিজনেস মডেলের নিশ্চয়তা\" box_description=\"আমাদের পরামর্শ ও দিকনির্দেশনার মাধ্যমে আপনি আপনার ব্যবসাকে এমন একটি অবস্থানে নিতে পারবেন, যেখানে দুনিয়ার সাফল্য এবং আখিরাতের কল্যাণ একত্রে অর্জন সম্ভব।\" quantity=\"4\" title_1=\"ইসলামিক বিজনেস মডেল তৈরি\" percent_1=\"100\" title_2=\"প্রযুক্তি নির্ভর উদ্ভাবন\" percent_2=\"90\" title_3=\"প্রশিক্ষণ ও দক্ষতা উন্নয়ন\" percent_3=\"99\" title_4=\"স্ট্র্যাটেজি ও পরিকল্পনা\" percent_4=\"95\" enable_lazy_loading=\"yes\"][/intro-video]</shortcode><shortcode>[featured-projects style=\"style-2\" title=\"পরামর্শ এবং সেবা পেতে আমাদের সাথে যোগাযোগ করুন\" subtitle=\"আপনার প্রয়োজন অনুযায়ী কাস্টমাইজড সেবা পেতে আজই আমাদের সাথে যোগাযোগ করুন।\" description=\"আপনার ব্যবসায়িক লক্ষ্য অর্জনে আমরা এখানে আপনার পাশে আছি। ইসলামিক বিজনেস মডেল, প্রযুক্তি সমাধান, এবং নৈতিক পরামর্শ প্রদান করে আমরা আপনাকে দুনিয়া ও আখিরাতে সফলতার পথে এগিয়ে নিতে সহায়তা করি।\" enable_lazy_loading=\"no\"][/featured-projects]</shortcode><shortcode>[request-quote title=\"যেকোনো সেবা গ্রহণ করতে এখনই যোগাযোগ করুন\" subtitle=\"GET A Service faster\" image=\"untitled-500-x-1000-px.png\" background_image=\"backgrounds/about-shape03.png\" enable_lazy_loading=\"yes\"][/request-quote]</shortcode><p>&nbsp;</p><figure class=\"image\"><img style=\"aspect-ratio:1200/1200;\" src=\"https://workshopit.info/storage/2-1.png\" alt=\"2-1.png\" width=\"1200\" height=\"1200\"></figure><figure class=\"image\"><img style=\"aspect-ratio:1200/1200;\" src=\"https://workshopit.info/storage/1-2.png\" alt=\"1-2.png\" width=\"1200\" height=\"1200\"></figure><figure class=\"image\">&nbsp;</figure><shortcode>[testimonials style=\"style-1\" title=\"আমাদের সম্পর্কে ক্লায়েন্টের মতামত\" subtitle=\"ক্লায়েন্টের মূল্যবান মতামত:\" testimonial_ids=\"5,6,7,8\" background_image=\"backgrounds/testimonial-bg.png\" enable_lazy_loading=\"yes\"][/testimonials]</shortcode><p>&nbsp;</p>', 1, NULL, 'homepage', 'Consulting in Bangladesh- বিজনেস ও প্রযুক্তি পরামর্শদাতা আপনার ব্যবসা ও প্রযুক্তি উদ্যোগকে এগিয়ে নিয়ে যাওয়ার জন্য আমাদের ব্লগ হতে পারে আপনার নির্ভরযোগ্য পরামর্শদাতা।', 'published', '2025-01-17 18:19:32', '2025-03-14 17:09:22'),
(2, 'Start Your Online Business', '<shortcode>[hero-banner style=\"style-2\" title=\"Start Your Online Business – Step-by-Step Guide to Success\" description=\"Welcome to Start Your Online Business—your ultimate resource for launching and growing a successful online venture. Whether you\'re a beginner or an experienced entrepreneur, we provide step-by-step guides, expert tips, and the latest tools to help you build your dream business. Explore strategies for e-commerce, affiliate marketing, digital products, and more. Take the first step toward financial freedom today! Want it more formal, concise, or targeting a specific business type? Let me know!\" image=\"galleries/5.png\" image_1=\"backgrounds/consulting-banner-img02.png\" image_2=\"general/consulting-banner-img03.png\" background_image_1=\"backgrounds/consulting-banner-shape01.png\" background_image_2=\"backgrounds/about-shape01.png\"][/hero-banner]</shortcode><shortcode>[brands title=\"Trusted by 10,000+ companies around the world\" quantity=\"5\" name_1=\"Zelus\" image_1=\"brands/brand-img04.png\" link_1=\"https://zelus.com\" name_2=\"The bird\" image_2=\"brands/brand-img05.png\" link_2=\"https://thebird.com\" name_3=\"Nature Wave\" image_3=\"brands/brand-img03.png\" link_3=\"https://naturewave.com\" name_4=\"Start\" image_4=\"brands/brand-img01.png\" link_4=\"https://start.com\" name_5=\"Finance\" image_5=\"brands/brand-img02.png\" link_5=\"https://finance.com\" style=\"style-2\"][/brands]</shortcode><shortcode>[featured-service-categories style=\"style-2\" title=\"The features that make our Service unique\" subtitle=\"WHAT WE DO FOR YOU\" category_ids=\"3,4,5,7\" enable_lazy_loading=\"no\"][/featured-service-categories]</shortcode><shortcode>[about-us-information style=\"style-8\" title=\"Building Your Own Startup Has Been Simpler\" subtitle=\"Who We are\" description=\"Transforming the Business Landscape: Leading a New Era of Excellence, Innovation, and Sustainability in Solutions and Leadership for Unpre