INSERT INTO `pf_packages` (`id`, `name`, `description`, `content`, `price`, `annual_price`, `duration`, `features`, `status`, `is_popular`, `action_label`, `action_url`, `created_at`, `updated_at`, `order`) VALUES
(1, 'Business Consultant', '1 Business Consultant per month For professionals who need strategic insights to grow their businesses.', '<p>For professionals who need strategic insights to grow their businesses.</p><p><strong>Price:</strong> $50/month<br><strong>Services Offered:</strong></p><ul><li><strong>Strategic Planning</strong>: Crafting business strategies to achieve your goals.</li><li><strong>Market Analysis</strong>: In-depth research to identify opportunities and trends.</li><li><strong>Operational Efficiency</strong>: Suggestions to streamline business processes.</li><li><strong>Financial Consulting</strong>: Budget planning and cost optimization advice.</li><li><strong>Team Management Support</strong>: Guidance on leadership and organizational structures.</li><li><strong>Monthly Consultation</strong>: 1-on-1 session with an expert Business Consultant.</li><li><h3>Why Choose Us?</h3></li><li><strong>No Hidden Charges</strong>: Transparent pricing with no surprises.</li><li><strong>Customizable Plans</strong>: Tailored services to match your unique business needs.</li><li><strong>Expert Consultants</strong>: Access to industry professionals with proven expertise.</li><li><strong>Reliable Support</strong>: Ongoing assistance to ensure success.</li><li><strong>Pick your plan today and let us take your business to new heights!</strong></li></ul>', '$40', '$400', 'monthly', '+Strategic Planning: Crafting business strategies to achieve your goals.\r\n+Market Analysis: In-depth research to identify opportunities and trends.\r\n+Operational Efficiency: Suggestions to streamline business processes.\r\n+Financial Consulting: Budget planning and cost optimization advice.\r\n+Team Management Support: Guidance on leadership and organizational structures.\r\n+Monthly Consultation: 1-on-1 session with an expert Business Consultant.', 'published', 1, 'Get The Plan Now', '/contact', '2025-01-17 18:19:35', '2025-01-24 23:39:27', 0),
(2, 'IT & Cybersecurity Consultant', 'IT and Cybersecurity 1 Consultant Per Month, Perfect for businesses starting their IT journey or enhancing their cybersecurity.', '<p>Perfect for businesses starting their IT journey or enhancing their cybersecurity.</p><p><strong>Price:</strong> $49/month<br><strong>Services Offered:</strong></p><ul><li><strong>IT Infrastructure Setup and Management</strong>:<br>Assistance with setting up and managing hardware, software, and networking systems.</li><li><strong>Cloud Solutions</strong>:<br>Migration, setup, and management of cloud services like AWS, Google Cloud, and Microsoft Azure.</li><li><strong>System Updates and Maintenance</strong>:<br>Regular system updates to enhance performance and resolve technical glitches.</li><li><strong>IT Troubleshooting</strong>:<br>Quick resolution of IT issues through remote support.</li><li><strong>Cybersecurity Audit</strong>: Evaluating vulnerabilities in your system.</li><li><strong>Data Protection</strong>: Implementing best practices for secure data storage and access.</li><li><strong>Threat Detection and Response</strong>: Proactive monitoring and incident handling.</li><li><strong>Compliance Support</strong>: Ensuring your business meets industry standards like GDPR or ISO.</li><li><strong>Regular Updates</strong>: 3-time updates per month to keep systems secure.</li></ul><hr><h3>Why Choose Us?</h3><ul><li><strong>No Hidden Charges</strong>: Transparent pricing with no surprises.</li><li><strong>Customizable Plans</strong>: Tailored services to match your unique business needs.</li><li><strong>Expert Consultants</strong>: Access to industry professionals with proven expertise.</li><li><strong>Reliable Support</strong>: Ongoing assistance to ensure success.</li></ul><p><strong>Pick your plan today and let us take your business to new heights!</strong></p>', '$50', '$500', 'monthly', '+IT Infrastructure Setup and Management: Assistance with setting up and managing hardware, software, and networking systems.\r\n+Cloud Solutions: Migration, setup, and management of cloud services like AWS, Google Cloud, and Microsoft Azure.\r\n+System Updates and Maintenance: Regular system updates to enhance performance and resolve technical glitches.\r\n+IT Troubleshooting: Quick resolution of IT issues through remote support.\r\n+Cybersecurity Audit: Evaluating vulnerabilities in your system.', 'published', 1, 'Get The Plan Now', '/contact', '2025-01-17 18:19:35', '2025-02-19 11:49:37', 0),
(3, 'Content and Digital Marketing Consultant', 'Content and Digital Marketing 1 Consultant Per Month, Ideal for businesses aiming to enhance their online presence and marketing efforts.', '<p>Ideal for businesses aiming to enhance their online presence and marketing efforts.</p><p><strong>Price:</strong> $50/month<br><strong>Services Offered:</strong></p><ul><li><strong>Content Strategy</strong>: Planning engaging and SEO-friendly content.</li><li><strong>Social Media Management</strong>: Boosting presence on platforms like Facebook, Instagram, and LinkedIn.</li><li><strong>Email Marketing Campaigns</strong>: Designing and executing effective campaigns.</li><li><strong>PPC and Ads Management</strong>: Optimizing paid advertisements for better ROI.</li><li><strong>Analytics and Reporting</strong>: Detailed performance insights to refine strategies.</li><li><strong>Monthly Consultation</strong>: 1-on-1 session with a Digital Marketing Consultant.</li></ul><hr><h3>Why Choose Us?</h3><ul><li><strong>No Hidden Charges</strong>: Transparent pricing with no surprises.</li><li><strong>Customizable Plans</strong>: Tailored services to match your unique business needs.</li><li><strong>Expert Consultants</strong>: Access to industry professionals with proven expertise.</li><li><strong>Reliable Support</strong>: Ongoing assistance to ensure success.</li></ul><p><strong>Pick your plan today and let us take your business to new heights!</strong></p>', '$40', '$400', 'monthly', '+Content Strategy: Planning engaging and SEO-friendly content.\r\n+Social Media Management: Boosting presence on platforms like Facebook, Instagram, and LinkedIn.\r\n+Email Marketing Campaigns: Designing and executing effective campaigns.\r\n+PPC and Ads Management: Optimizing paid advertisements for better ROI.\r\n+Analytics and Reporting: Detailed performance insights to refine strategies.\r\n+Monthly Consultation: 1-on-1 session with a Digital Marketing Consultant.', 'published', 1, 'Get The Plan Now', '/contact', '2025-01-17 18:19:35', '2025-01-24 23:40:20', 0),
(4, 'Business Consultant bd', 'Business Consultant', '<p><a style=\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:border-box;color:rgba(var(--bb-link-color-rgb),var(--bb-link-opacity,1));font-family:Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, &quot;Helvetica Neue&quot;, Arial, sans-serif, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;;font-size:14px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;orphans:2;scrollbar-color:rgba(var(--bb-scrollbar-color,var(--bb-body-color-rgb)),.16);scrollbar-width:thin !important;text-align:left;text-decoration-skip-ink:auto;text-decoration:none;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\" href=\"https://workshopit.info/admin/portfolio/packages/edit/1\" title=\"Business Consultant\">Business Consultant</a></p>', '৳4000', '৳40,000', 'monthly', 'Business Consultant', 'published', 1, 'Contact us', '/contact', '2025-01-24 23:34:13', '2025-01-24 23:34:13', 0),
